const cfg = $('Alert Configuration').first().json || {};
const labels = $input.all().map(item => item.json || {});

function findLabelId(name) {
  const match = labels.find(label =>
    String(label.name || '').trim() === String(name || '').trim()
  );
  return match ? String(match.id || '') : '';
}

function gmailLabelToken(name) {
  return String(name || '')
    .trim()
    .replace(/\s+/g, '-');
}

const sourceLabelId = findLabelId(cfg.source_label);
const processedLabelId = findLabelId(cfg.processed_label);
const reviewLabelId = findLabelId(cfg.review_label);

const missing = [];
if (!sourceLabelId) missing.push(cfg.source_label);
if (!processedLabelId) missing.push(cfg.processed_label);
if (!reviewLabelId) missing.push(cfg.review_label);

if (missing.length) {
  throw new Error(
    'Crie estas labels no Gmail antes do teste: ' +
    missing.join(', ')
  );
}

/*
  A busca inicial usa somente remetente e labels.
  A validação de assunto, corpo e autenticação acontece
  depois. Assim, uma mudança no template do LinkedIn
  vai para Review em vez de desaparecer silenciosamente.
*/
const gmailQuery = [
  'from:' + cfg.allowed_sender,
  'label:' + gmailLabelToken(cfg.source_label),
  '-label:' + gmailLabelToken(cfg.processed_label),
  '-label:' + gmailLabelToken(cfg.review_label)
].join(' ');

return [{
  json: {
    ...cfg,
    source_label_id: sourceLabelId,
    processed_label_id: processedLabelId,
    review_label_id: reviewLabelId,
    gmail_query: gmailQuery
  }
}];

function collectRuns(name, maxRuns) {
  const collected = [];

  for (let runIndex = 0; runIndex < maxRuns; runIndex++) {
    try {
      const items = $(name).all(0, runIndex);

      if (Array.isArray(items)) {
        collected.push(...items);
      }
    } catch {
      // O node pode não ter executado nesta iteração.
    }
  }

  return collected;
}

let foundItems = [];

try {
  foundItems =
    $('Gmail - Find Unprocessed Alerts').all();
} catch {
  foundItems = [];
}

const maxRuns = foundItems.length;

const processedItems =
  collectRuns('Gmail - Mark Processed', maxRuns);

const reviewItems =
  collectRuns('Gmail - Mark for Review', maxRuns);

const extractedItems =
  collectRuns('Extract LinkedIn Alert Jobs', maxRuns);

const processedIds = new Set(
  processedItems
    .map(item => String(item.json?.id || ''))
    .filter(Boolean)
);

const reviewIds = new Set(
  reviewItems
    .map(item =>
      String(
        item.json?.id ||
        item.json?.email_id ||
        ''
      )
    )
    .filter(Boolean)
);

const jobsExtracted =
  extractedItems.reduce(
    (total, item) =>
      total + Number(item.json?.job_count || 0),
    0
  );

return [{
  json: {
    status: 'completed',
    source: 'LinkedIn Alert',
    emails_found:
      foundItems.length,
    emails_processed:
      processedIds.size,
    emails_for_review:
      reviewIds.size,
    jobs_extracted:
      jobsExtracted,
    message:
      'LinkedIn Job Alerts Gmail check completed.'
  }
}];

const email = $input.first().json || {};
const cfg = $('Resolve Alert Labels').first().json || {};
const headers = email.headers || {};

function decodeEntities(value) {
  return String(value || '')
    .replace(/&amp;/gi, '&')
    .replace(/&quot;/gi, '"')
    .replace(/&#39;|&apos;/gi, "'")
    .replace(/&lt;/gi, '<')
    .replace(/&gt;/gi, '>')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&middot;|&#183;|&#xB7;/gi, '·')
    .replace(/&#(\d+);/g, (_, number) => String.fromCharCode(Number(number)))
    .replace(/&#x([0-9a-f]+);/gi, (_, number) => String.fromCharCode(parseInt(number, 16)));
}

function htmlToText(value) {
  return decodeEntities(value)
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(?:p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/ *\n */g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function cleanLine(value) {
  return String(value || '').replace(/\s+/g, ' ').trim();
}

function normalizeSender(value) {
  const text = String(value || '').trim().toLowerCase();
  const bracket = text.match(/<([^>]+)>/);
  return (bracket ? bracket[1] : text).trim();
}

function decodedCandidates(rawUrl) {
  const values = [];
  let current = decodeEntities(rawUrl);
  for (let index = 0; index < 4; index++) {
    if (!current || values.includes(current)) break;
    values.push(current);
    try {
      const decoded = decodeURIComponent(current);
      if (decoded === current) break;
      current = decoded;
    } catch {
      break;
    }
  }
  const nested = [];
  for (const value of values) {
    try {
      const parsed = new URL(value);
      for (const key of ['url', 'redirect', 'redirectUrl', 'dest', 'destination', 'target', 'continue']) {
        const candidate = parsed.searchParams.get(key);
        if (candidate) nested.push(...decodedCandidates(candidate));
      }
    } catch {}
  }
  return [...new Set([...values, ...nested])];
}

function jobIdFromUrl(rawUrl) {
  for (const candidate of decodedCandidates(rawUrl)) {
    const pathMatch =
      candidate.match(/\/(?:comm\/)?jobs\/view\/(?:[^/?#]*-)?(\d{7,12})(?:[/?#]|$)/i) ||
      candidate.match(/\/(?:comm\/)?jobs\/view\/(\d{7,12})/i);
    if (pathMatch) return pathMatch[1];

    try {
      const parsed = new URL(candidate);
      for (const key of ['currentJobId', 'jobId', 'job_id']) {
        const value = parsed.searchParams.get(key);
        if (/^\d{7,12}$/.test(String(value || ''))) return String(value);
      }
    } catch {}

    const queryMatch = candidate.match(/(?:currentJobId|jobId|job_id)(?:=|%3D|:)(\d{7,12})/i);
    if (queryMatch) return queryMatch[1];
  }
  return '';
}

function formatBrazilDateTime(value) {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) return '';
  const parts = new Intl.DateTimeFormat('en-US', {
    timeZone: cfg.timezone || 'UTC',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  }).formatToParts(date).reduce((result, part) => {
    result[part.type] = part.value;
    return result;
  }, {});
  return parts.day + '/' + parts.month + '/' + parts.year + ' ' + parts.hour + ':' + parts.minute;
}

function detectWorkMode(value) {
  const text = String(value || '').toLowerCase();
  if (/\b(remote|remoto|remota)\b/i.test(text)) return 'Remote';
  if (/\b(hybrid|híbrido|hibrido|híbrida|hibrida)\b/i.test(text)) return 'Hybrid';
  if (/\b(on-site|onsite|on site|presencial)\b/i.test(text)) return 'On-site';
  return '';
}

const subject = cleanLine(email.subject || headers.subject || '');
const sender =
  email.from?.value?.[0]?.address ||
  email.from?.text ||
  headers.from ||
  '';
const normalizedSender = normalizeSender(sender);
const html = String(email.html || email.textAsHtml || '');
const plainText = String(email.text || htmlToText(html));
const bodyKeywordMatch = plainText.match(/Your job alert for\s+(.+?)\s+\d+\s+new jobs?\b/i);
const subjectKeywordMatch = subject.match(/^[“"](.+?)[”"]\s*:/);
const detectedKeyword = cleanLine(
  subjectKeywordMatch?.[1] ||
  bodyKeywordMatch?.[1] ||
  ''
);
const override = Array.isArray(cfg.keyword_overrides)
  ? cfg.keyword_overrides.find(rule =>
      cleanLine(rule.alert_identifier).toLowerCase() === detectedKeyword.toLowerCase()
    )
  : null;
const searchKeyword = cleanLine(override?.search_keyword || detectedKeyword);

function parseSubjectPostedDate(value) {
  const match = String(value || '').match(
    /posted on\s+(\d{1,2})\/(\d{1,2})\/(\d{2,4})\b/i
  );

  if (!match) {
    return {
      date_posted: '',
      posted_at: ''
    };
  }

  const month = Number(match[1]);
  const day = Number(match[2]);
  let year = Number(match[3]);

  if (year < 100) {
    year += 2000;
  }

  const iso =
    String(year).padStart(4, '0') + '-' +
    String(month).padStart(2, '0') + '-' +
    String(day).padStart(2, '0');

  const parsed = new Date(iso + 'T12:00:00Z');

  if (
    Number.isNaN(parsed.getTime()) ||
    parsed.getUTCFullYear() !== year ||
    parsed.getUTCMonth() + 1 !== month ||
    parsed.getUTCDate() !== day
  ) {
    return {
      date_posted: '',
      posted_at: ''
    };
  }

  return {
    date_posted:
      String(day).padStart(2, '0') + '/' +
      String(month).padStart(2, '0') + '/' +
      String(year).padStart(4, '0'),
    posted_at: iso
  };
}

const subjectPosted =
  parseSubjectPostedDate(subject);

const authenticationHeader = String(
  headers['authentication-results'] ||
  headers['arc-authentication-results'] ||
  ''
);
const authenticationOk =
  !authenticationHeader ||
  (
    /dkim=pass/i.test(authenticationHeader) &&
    /(?:header\.(?:d|i)=|@)(?:[\w.-]+\.)?linkedin\.com/i.test(authenticationHeader)
  );

const senderOk = normalizedSender === String(cfg.allowed_sender || '').toLowerCase();
const subjectOk =
  Boolean(searchKeyword) &&
  /posted on\s+\d{1,2}\/\d{1,2}\/\d{2,4}\b/i.test(subject);
const bodyOk =
  /Your job alert for\b/i.test(plainText) &&
  /\bnew jobs?\b/i.test(plainText);

const anchors = [];
const anchorPattern = /<a\b[^>]*href\s*=\s*(["'])(.*?)\1[^>]*>([\s\S]*?)<\/a>/gi;
let anchorMatch;
while ((anchorMatch = anchorPattern.exec(html)) !== null) {
  anchors.push({
    start: anchorMatch.index,
    end: anchorPattern.lastIndex,
    href: decodeEntities(anchorMatch[2]),
    text: cleanLine(htmlToText(anchorMatch[3]))
  });
}

const candidates = [];
let unparsedJobLinks = 0;
for (const anchor of anchors) {
  const looksLikeJobView =
    /jobs(?:\/|%2f)view(?:\/|%2f)/i.test(anchor.href) ||
    /(?:currentJobId|jobId|job_id)(?:=|%3D|:)/i.test(anchor.href);
  if (!looksLikeJobView) continue;

  const jobId = jobIdFromUrl(anchor.href);
  if (!jobId) {
    unparsedJobLinks++;
    continue;
  }

  const nearbyHtml = html.slice(anchor.end, Math.min(anchor.end + 1800, html.length));
  const nearbyLines = htmlToText(nearbyHtml)
    .split('\n')
    .map(cleanLine)
    .filter(Boolean)
    .filter(line =>
      !/^(Actively recruiting|Easy Apply|\d+\s+(?:school alumni|connections?)|View job|View jobs)$/i.test(line)
    );

  let title = anchor.text;
  if (
    !title ||
    /^(LinkedIn|View job|View jobs|Apply|See more)$/i.test(title)
  ) {
    title = 'Not specified';
  }

  let companyName = '';
  let location = '';
  let workMode = '';

  const detailLine = nearbyLines.find(line => /[·•]/.test(line));
  if (detailLine) {
    const detailMatch = detailLine.match(/^(.+?)\s*[·•]\s*(.+)$/);
    if (detailMatch) {
      companyName = cleanLine(detailMatch[1]);
      const locationWithMode = cleanLine(detailMatch[2]);
      workMode = detectWorkMode(locationWithMode);
      location = cleanLine(
        locationWithMode.replace(/\s*\((?:Remote|Remoto|Remota|Hybrid|Híbrido|Hibrido|Híbrida|Hibrida|On-site|On site|Presencial)\)\s*$/i, '')
      );
    }
  }

  candidates.push({
    job_id: jobId,
    status: 'To do',
    date_scraped: formatBrazilDateTime(new Date()),
    source: 'LinkedIn Alert',
    search_keyword: searchKeyword,
    date_posted: subjectPosted.date_posted,
    title,
    work_mode: workMode,
    url: 'https://www.linkedin.com/jobs/view/' + jobId,
    company_name: companyName,
    location,
    description: '',
    language: '',
    payment: '',
    time_type: '',
    job_type: '',
    experience: '',
    salary: '',
    match: '',
    qualified: '',
    cover_letter: '',
    notes: '',
    interview_at: '',
    invite_meet: '',
    attended: false,
    posted_at: subjectPosted.posted_at,
    scraped_at: new Date().toISOString()
  });
}

function completeness(job) {
  return ['title', 'company_name', 'location', 'work_mode']
    .reduce((score, field) => score + (String(job[field] || '').trim() ? 1 : 0), 0);
}

const jobsById = new Map();
for (const job of candidates) {
  const current = jobsById.get(job.job_id);
  if (!current || completeness(job) > completeness(current)) {
    jobsById.set(job.job_id, job);
  }
}
const jobs = [...jobsById.values()];

const problems = [];
if (!senderOk) problems.push('unexpected_sender');
if (!subjectOk) problems.push('unexpected_subject');
if (!bodyOk) problems.push('missing_job_alert_markers');
if (!authenticationOk) problems.push('linkedin_authentication_failed');
if (!jobs.length) problems.push('no_linkedin_job_ids');
if (unparsedJobLinks) problems.push('unparsed_job_links:' + unparsedJobLinks);

return [{
  json: {
    email_id: String(email.id || email.messageId || ''),
    thread_id: String(email.threadId || ''),
    subject,
    sender: normalizedSender,
    search_keyword: searchKeyword,
    jobs,
    job_count: jobs.length,
    unparsed_job_link_count: unparsedJobLinks,
    ready_for_job_saver: problems.length === 0,
    review_reasons: problems
  }
}];

const email = $input.first().json || {};
const jobs = Array.isArray(email.jobs) ? email.jobs : [];
return jobs.map(job => ({
  json: {
    ...job,
    _gmail_message_id: email.email_id,
    _gmail_subject: email.subject
  },
  pairedItem: {
    item: 0
  }
}));
